  const goldRow = $('goldRow'), goldVal = $('goldVal'), goldStatVal = $('goldStatVal');
  const shopBtn = $('shopBtn'), equipBtn = $('equipBtn'), questBtn = $('questBtn');
  const shopBox = $('shopBox'), equipBox = $('equipBox'), questBox = $('questBox');
