          mumyeong:{d:'공(空)의 일격 (피해 +10%, 치명 +8%)',f:(p)=>{p.dmgMult*=1.1;p.critChance=Math.min(0.9,p.critChance+0.08);}},
          necro:{d:'명계의 길 (부활 +1)',f:(p)=>{p.reviveLeft=(p.reviveLeft||0)+1;}},
