        for (let k=0;k<32;k++){ const a2=(Math.PI*2/32)*k; hostileShot(b.x, b.y, a2, 150, 7, 62*ds, 4); }
        b.dmg = Math.round(b.dmg*1.6); b.speed *= 1.3;
